import {orbitSources} from './orbits.js';
import {observationMarkup} from './observations.js';
import {telemetryMarkup} from './telemetry.js';
import {mountLab} from './lab.js';
import {t,initLanguages,getLanguage} from './i18n.js';
import {MissionWorld} from './world3d.js';
import {tickMission} from './mission-loop.js';
import {stories,chapters} from './story.js';
import {missions,modules,sources,scienceObjectives,configure,solarPower,energyStep} from './science.js';
const $=id=>document.getElementById(id),canvas=$('world');
let world;try{world=new MissionWorld(canvas);}catch(error){document.body.innerHTML='<main style="padding:40px;color:white;background:#101b29;min-height:100vh"><h1>3D graphics unavailable</h1><p>This version needs WebGL 2. Enable browser hardware acceleration or try a browser with WebGL 2 support, then reload.</p><button onclick="location.reload()">Reload</button></main>';throw error;}
const pointer={active:false,x:0,y:0};const pendingKeys=new Set();let briefStep=0;
let scale=1,now=0,last=0,state='hangar',mission=missions[0],selection={power:'solar',payload:'camera',comms:'compact',launcher:'light',objective:'mapping',altitude:100},cfg,keys=new Set(),run=null,sound=false,audio=null,noticeTime=0,libraryReturn='hangar',best={};
try{best=JSON.parse(localStorage.getItem('astra-best-v4')||'{}');}catch{}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function resize(){world.resize();}
addEventListener('resize',resize);resize();
function beep(freq=440,duration=.08){if(!sound)return;try{audio??=new AudioContext();audio.resume();let o=audio.createOscillator(),v=audio.createGain();o.type='triangle';o.frequency.value=freq;v.gain.setValueAtTime(.025,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function announce(message){$('notice').textContent=message;noticeTime=6;}
function setOverlay(html){$('overlay').innerHTML=html;keys.clear();pendingKeys.clear();pointer.active=false;$('app').dataset.mode=state;}
function showHangar(){state='hangar';run=null;$('hud').classList.add('hidden');$('touch').classList.add('hidden');renderHangar();}
function renderHangar(){cfg=configure(selection,mission);setOverlay(`<section class="hangar"><div class="hero"><div><div class="eyebrow">AN ENGINEER'S ODYSSEY · 2.5D FIELD SIMULATOR</div><h1>BUILD. EXPLORE.<br><em>UNDERSTAND.</em></h1><p>Your next discovery starts with a decision. Build a spacecraft, brave the field, and bring the science home.</p></div><div class="record">MISSION ARCHIVE<strong>${Object.values(best).filter(x=>x>0).length} / 3 destinations</strong>Learn through each attempt.<br>Return with a better design.</div></div><div class="section-title">01 / CHOOSE YOUR FRONTIER <span>TRAINING CAMPAIGN</span></div><div class="destinations">${missions.map(m=>`<button class="destination ${m.id===mission.id?'active':''}" data-mission="${m.id}" aria-pressed="${m.id===mission.id}"><div class="planet ${m.id}"></div><small>${m.tag}</small><h2>${m.name}</h2><p>${m.au} AU FROM THE SUN · ${m.gravity} m/s²</p></button>`).join('')}</div><div class="section-title">02 / DEFINE THE SCIENCE <span>QUESTION → EVIDENCE → INSTRUMENT</span></div><div class="science-objectives">${scienceObjectives.map(o=>`<button class="science-choice ${cfg.objective.id===o.id?'active':''}" data-objective="${o.id}" aria-pressed="${cfg.objective.id===o.id}"><strong>${o.name}</strong><p>${o.question}</p><small>${o.requirement}</small></button>`).join('')}</div><div class="workshop"><div><div class="section-title">03 / ENGINEER YOUR LOADOUT <span>EVERY CHOICE HAS A COST</span></div><div class="module-grid">${Object.entries(modules).map(([key,items])=>`<div class="module-group"><label>${key==='comms'?'Communications':key}</label>${items.map(m=>`<button class="module ${selection[key]===m.id?'active':''}" data-group="${key}" data-module="${m.id}" aria-pressed="${selection[key]===m.id}"><span class="radio"></span><span><strong>${m.name}</strong><small>${m.detail}</small></span></button>`).join('')}</div>`).join('')}</div></div><aside class="preflight"><div class="eyebrow">PREFLIGHT / DESIGN REVIEW</div><h3>${mission.name}</h3><div class="stat-line">Budget <b class="${cfg.cost>165?'bad':''}">${cfg.cost} / 165 cr</b></div><div class="stat-line">Launch mass <b class="${cfg.mass>cfg.launcher.capacity?'bad':''}">${cfg.mass.toFixed(1)} / ${cfg.launcher.capacity} kg</b></div><div class="stat-line">Transfer propellant <b data-no-translate>${cfg.orbit.propellant.toFixed(1)} kg</b></div><div class="stat-line">Planned orbit <b data-no-translate>${cfg.orbit.altitude} km</b></div><div class="stat-line">Sunlit power <b>${Math.round(cfg.generation)} W</b></div><div class="stat-line">Peak demand <b>${cfg.demand} W</b></div><div class="stat-line">Battery capacity <b>30 Wh</b></div><p class="science-note">${cfg.errors.length?`<span class="bad">${cfg.errors.join(' ')}</span>`:cfg.generation<cfg.demand?'Power deficit at peak load. Battery time is limited: scan deliberately and return before depletion.':'Design fits the launch limits. Watch the battery when sunlight disappears.'}</p><button id="open-lab" class="secondary lab-entry">ORBITAL LAB ↗</button><button id="launch" class="primary" ${cfg.errors.length?'disabled':''}>DEPLOY SIMULATION <span>↗</span></button></aside></div><p class="bottom-note">WASD: move · Mouse / J: strike · Right mouse / K: bolt · Space: dash · E: scan · Q: pulse<br>3D adventure with pixel-art UI. Fictional reconstruction and accelerated science models; sources and limits are in the Field Codex.</p></section>`);
 document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{mission=missions.find(m=>m.id===b.dataset.mission);renderHangar();beep(350);});document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{selection[b.dataset.group]=b.dataset.module;renderHangar();beep(500);});document.querySelectorAll('[data-objective]').forEach(b=>b.onclick=()=>{selection.objective=b.dataset.objective;renderHangar();});$('launch').onclick=start;$('open-lab').onclick=()=>{state='lab';setOverlay('');mountLab($('overlay'),mission,cfg,showHangar,altitude=>{selection.altitude=altitude;showHangar();});};
}
function beginRun(){cfg=configure(selection,mission);if(cfg.errors.length)return;run={targetData:cfg.objective.target,objective:cfg.objective.id,time:0,hp:100,wh:30,heat:0,stored:0,returned:0,scans:0,kills:0,damage:0,dash:0,pulse:0,invuln:0,upgrade:false,field:'sunlight',light:1,gen:cfg.generation,contact:true,scanTime:0,finished:false,log:[],p:{x:0,y:210,dx:0,dy:-1},nodes:[{x:-225,y:-70,done:false},{x:205,y:-180,done:false},{x:265,y:155,done:false}],enemies:[],shots:[],sparks:[],rings:[],spawn:2,up:{shield:1,cooling:1,rate:1},attackCd:0,special:0,attackAnim:0,comboWindow:0,combo:0,attacks:0,shake:0,dashTime:0,moving:false,aim:{x:0,y:-1},nextId:0,bossSpawned:false,bossDefeated:false,decisionMade:false,powerMode:'full'};state='play';setOverlay('');$('hud').classList.remove('hidden');$('touch').classList.remove('hidden');$('location').textContent=mission.name;$('task').textContent=cfg.objective.requirement;announce('Find the three glowing sites. Hold E nearby to scan.');beep(650,.18);}

function start(){cfg=configure(selection,mission);if(cfg.errors.length)return;run=null;briefStep=0;state='briefing';$('hud').classList.add('hidden');$('touch').classList.add('hidden');briefing();}
function briefing(){state='briefing';const story=stories[mission.id],text=[story.signal,story.question,story.goal][briefStep];setOverlay('<section class="story-screen"><div class="story-kicker">ASTRA FORGE / ARCHIVE 07</div><div class="story-card"><div class="eyebrow">'+chapters[briefStep]+'</div><h1>'+story.title+'</h1><div class="radio-line"><span class="radio-avatar">L</span><span>LYRA / MISSION ARCHIVE</span><span class="signal-bars">▂▄▆█</span></div><p class="story-text">'+text+'</p><p class="story-note">Original fiction. Engineering inspired by NASA learning resources.</p><div class="story-progress">'+[0,1,2].map(i=>'<i class="'+(i<=briefStep?'active':'')+'"></i>').join('')+'</div><button class="primary" id="story-next">'+(briefStep===2?'ENTER THE RECONSTRUCTION →':'FOLLOW THE SIGNAL →')+'</button><button class="text-button" id="story-skip">Skip briefing</button></div></section>');$('story-next').onclick=()=>{beep(460,.08);if(briefStep<2){briefStep++;briefing();}else beginRun();};$('story-skip').onclick=beginRun;}
function decision(){state='decision';const story=stories[mission.id],source=sources.find(s=>s.id===story.source);setOverlay('<section class="modal decision-modal"><div class="eyebrow">LYRA / ENGINEERING DECISION</div><h1>The mission needs a choice.</h1><p>'+story.question+'</p><div class="cards"><button class="upgrade" id="conserve"><strong>Conserve energy</strong><p>Reduce idle demand from 80 W to 45 W. Instrument scans take 50% longer, leaving you exposed for longer.</p></button><button class="upgrade" id="full-power"><strong>Keep full performance</strong><p>Keep 80 W idle demand and normal scan speed. Finish faster, but consume more energy between observations.</p></button></div><p class="story-note">'+source.name+' · <a target="_blank" rel="noopener noreferrer" href="'+source.url+'">OPEN ORIGINAL RESOURCE ↗</a></p></section>');for(const [id,mode] of [['conserve','conserve'],['full-power','full']])$(id).onclick=()=>{run.powerMode=mode;run.log.push(mode==='conserve'?'Reduced idle load to 45 W; scan duration increased by 50%.':'Retained 80 W idle load and normal scan duration.');resume();announce(mode==='conserve'?'Load shedding active. Less power, longer exposure at each scan.':'Full performance active. Watch your battery reserve.');};}

function pause(){if(state==='play'){state='pause';setOverlay(`<section class="modal"><div class="eyebrow">FLIGHT HOLD</div><h1>Take a breath.</h1><p>WASD moves relative to the screen. Aim with the mouse and click to strike; right-click fires a bolt. Keyboard J strikes and K fires with assisted aim. Chain three strikes, dodge with Space, scan with E, and pulse with Q. Defeat the relay guardian, then deliver your data.</p><div class="buttons"><button class="primary" id="resume">RESUME MISSION →</button><button class="secondary" id="workshop">WORKSHOP</button></div></section>`);$('resume').onclick=resume;$('workshop').onclick=showHangar;}else if(state==='pause')resume();}
function resume(){state='play';setOverlay('');}
$('pause').onclick=pause;$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'SOUND ON':'SOUND OFF';beep();};$('abort').onclick=pause;
function codex(){libraryReturn=state;state='library';setOverlay(`<section class="library"><div class="library-top"><div><div class="eyebrow">KNOWLEDGE IS YOUR REAL UPGRADE</div><h1>Field codex</h1></div><button class="secondary" id="closeCodex">RETURN ↙</button></div><p>All nine resources from the <a href="https://www.spaceappschallenge.org/2026/challenges/space-mission-design-game/?tab=resources" target="_blank" rel="noopener noreferrer">2026 challenge resource list</a> are indexed below. Inclusion is not a claim of software integration or complete curriculum coverage.</p><p><b>Model:</b> solar power = array power at 1 AU ÷ distance² × illumination. Battery change = (generation − demand) × seconds ÷ 3600. One play second represents 30 electrical-system seconds. Scan energy, dash costs, hardware values, opponents, heat and contact windows are designed for gameplay. Terrain scale, travel, launch and timing are not realistic simulations. Gravity is informational in this version; The Orbital Laboratory separately models idealized two-body transfers; it does not drive surface contact windows. Live NASA data and full interplanetary flight remain future work.</p><div class="sources">${sources.map(s=>`<article class="source"><small>${s.status.toUpperCase()}</small><h3>${s.name}</h3><p>${s.use}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">OPEN ORIGINAL RESOURCE ↗</a></article>`).join('')}</div></section>`);$('closeCodex').onclick=()=>{if(libraryReturn==='hangar')showHangar();else if(libraryReturn==='play')resume();else if(libraryReturn==='pause'){state='play';pause();}else if(libraryReturn==='upgrade')upgrade();else if(libraryReturn==='briefing')briefing();else if(libraryReturn==='decision')decision();else if(libraryReturn==='result')result(run.finished);else showHangar();};}
$('library').onclick=()=>{if(state!=='library')codex();};
function upgrade(){state='upgrade';setOverlay(`<section class="modal"><div class="eyebrow">FIELD REVIEW / TWO SITES MAPPED</div><h1>Adapt your strategy.</h1><p>Choose one simulated subsystem improvement. Real hardware cannot be magically replaced during a mission; this is a training reward.</p><div class="cards"><button class="upgrade" data-up="shield"><strong>Fault protection · 30% less damage</strong><p>Preserve integrity while bringing your measurements home.</p></button><button class="upgrade" data-up="cooling"><strong>Thermal management · 60% faster cooling</strong><p>Recover from scan and pulse heat more quickly.</p></button><button class="upgrade" data-up="rate"><strong>Ground network · 50% faster downlink</strong><p>Clear the data buffer faster during contact windows.</p></button></div></section>`);document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{const k=b.dataset.up;run.up[k]=k==='shield'?.7:k==='cooling'?1.6:1.5;run.log.push(`Selected ${k} improvement after comparing constraints.`);resume();announce('Upgrade applied. Finish the survey and reach the uplink.');});}
function result(success){state='result';run.finished=success;updateHud();const score=Math.max(0,Math.round(Math.min(1,run.returned/run.targetData)*1000+run.hp*3+run.wh*5+(success?500:0)-run.time));if(success){best[mission.id]=Math.max(best[mission.id]||0,score);try{localStorage.setItem('astra-best-v4',JSON.stringify(best));}catch{}}const reason=success?'Your instrument collected measurements, and the ground segment received them. Science counts when it reaches its users.':run.wh<=0?'Battery exhausted. Your loads consumed energy faster than your power source could replace it. Compare generation and demand in the workshop.':'Integrity lost. Use dash invulnerability, pulse nearby hazards, and avoid warning circles.';setOverlay(`<section class="modal"><div class="eyebrow">MISSION DEBRIEF / ${success?'DATA RECEIVED':'LESSON RECOVERED'}</div><h1>${success?'Discovery delivered.':'Every attempt teaches.'}</h1><div class="results"><div><b>${score}</b>MISSION SCORE</div><div><b>${Math.floor(run.returned+1e-6)} MB</b>SCIENCE RETURNED</div><div><b>${Math.round(run.wh)} Wh</b>ENERGY REMAINING</div></div><p>${reason}</p><p>${run.powerMode==='conserve'?'You conserved energy: idle demand fell to 45 W, but scans took 50% longer.':'You kept full performance: idle demand stayed at 80 W and scans ran at normal speed.'}</p>${observationMarkup(run)}${telemetryMarkup(run)}<p><b>Engineering insight:</b> ${mission.lesson}</p><p>At ${mission.au} AU your selected source produced ${Math.round(cfg.generation)} W in full sunlight; peak load was ${cfg.demand} W. You mapped ${run.scans}/3 sites and took ${Math.round(run.damage)} damage. ${run.log.join(' ')}</p><p><a href="${sources.find(s=>s.id===mission.source).url}" target="_blank" rel="noopener noreferrer">Explore the science behind this run ↗</a></p><div class="buttons"><button class="primary" id="again">REDESIGN & RETRY →</button><button class="secondary" id="same">SAME LOADOUT</button><button class="secondary" id="export-report">EXPORT MISSION REPORT</button></div></section>`);$('again').onclick=showHangar;$('same').onclick=start;$('export-report').onclick=exportReport;document.querySelectorAll('[data-spectrum-answer]').forEach(b=>b.onclick=()=>{$('spectrum-feedback').textContent=b.dataset.spectrumAnswer==='2'?'Yes. Site 02 returns the least light near this wavelength. Identification would require calibrated reference spectra.':'Compare the curves near 1.5 μm: site 02 has the lowest reflectance. A deeper dip is not, by itself, a material identification.';});beep(success?880:180,.4);}
canvas.addEventListener('pointermove',event=>{const hit=world.aim(event.clientX,event.clientY);if(hit){Object.assign(pointer,hit);pointer.active=true;}});
canvas.addEventListener('pointerdown',event=>{if(state!=='play')return;canvas.setPointerCapture(event.pointerId);const hit=world.aim(event.clientX,event.clientY);if(hit)Object.assign(pointer,hit,{active:true});keys.add(event.button===2?'mouse2':'mouse0');pendingKeys.add(event.button===2?'mouse2':'mouse0');});
canvas.addEventListener('contextmenu',event=>event.preventDefault());addEventListener('pointerup',()=>{keys.delete('mouse0');keys.delete('mouse2');});
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k)&&state==='play')e.preventDefault();if(e.repeat)return;if(['w','a','s','d','j','k'].includes(k))pointer.active=false;if(k==='p'||k==='escape'){pause();return;}keys.add(k);if(['j','k','q',' '].includes(k))pendingKeys.add(k);});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>{keys.clear();if(state==='play')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='play')pause();});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);pendingKeys.add(b.dataset.key);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);});
function sparks(x,y,color,n=12){for(let i=0;i<n;i++)run.sparks.push({x,y,z:4,vx:(Math.random()-.5)*140,vy:(Math.random()-.5)*140,vz:Math.random()*60,life:.6+Math.random()*.5,color});}
function hurt(amount){if(run.invuln>0)return;const n=amount*run.up.shield;run.hp-=n;run.damage+=n;run.invuln=.7;run.shake=.25;run.scanTime=Math.max(0,run.scanTime-.4);sparks(run.p.x,run.p.y,'#f4a38b',8);beep(140);}
let hudTimer=0;function update(dt){if(state!=='play'||!run)return;const frameKeys=new Set([...keys,...pendingKeys]);pendingKeys.clear();tickMission(run,cfg,mission,frameKeys,dt,{pointer,announce,sparks,beep,hurt,decision,upgrade,result});if($('interaction').textContent!==t(run.prompt||''))$('interaction').textContent=t(run.prompt||'');if(noticeTime>0){noticeTime-=dt;if(noticeTime<=0)$('notice').textContent='';}hudTimer-=dt;if(hudTimer<=0){hudTimer=.1;updateHud();}}
function updateHud(){const r=run;$('hpText').textContent=Math.max(0,Math.round(r.hp))+'%';$('hpBar').style.width=clamp(r.hp,0,100)+'%';$('energyText').textContent=r.wh.toFixed(1)+' Wh';$('energyBar').style.width=r.wh/30*100+'%';$('heatText').textContent=Math.round(r.heat)+'%';$('heatBar').style.width=r.heat+'%';$('dataText').textContent=Math.floor(r.returned+1e-6)+' MB';$('powerText').textContent=Math.round(r.gen)+' W';$('condition').textContent=`${r.field.toUpperCase()} · ${r.contact?'CONTACT OPEN':'CONTACT CLOSED'} · Buffer: ${Math.ceil(r.stored)} MB · pulse ${r.pulse>0?r.pulse.toFixed(1)+'s':'ready'}`;$('clock').textContent=String(Math.floor(r.time/60)).padStart(2,'0')+':'+String(Math.floor(r.time%60)).padStart(2,'0');$('sector').textContent=String(Math.min(3,r.scans+1)).padStart(2,'0');$('objectives').innerHTML=`<div class="objective done"><span>✓</span> Design approved</div><div class="objective ${r.bossDefeated?'done':''}"><span>◇</span> ${r.bossDefeated?'Guardian defeated':'Restore the relay'}</div><div class="objective ${r.scans===3?'done':''}"><span>◇</span> Survey sites <b>${r.scans}/3</b></div><div class="objective ${r.returned>=r.targetData-.01?'done':''}"><span>◇</span> Return science <b>${Math.floor(r.returned+1e-6)}/${run.targetData} MB</b></div>`;}
function draw(dt){world.render(run,mission,state,now,dt);const nodes=run?.nodes||[];const labels=$('world-labels');labels.hidden=state!=='play';nodes.forEach((n,i)=>{const el=labels.children[i],p=world.project(n.x,n.y,2.3);el.style.transform='translate(-50%,-50%) translate('+p.x+'px,'+p.y+'px)';el.textContent=t(n.done?'MAPPED':'SITE '+(i+1));el.classList.toggle('mapped',n.done);});const boss=run?.enemies.find(e=>e.type==='boss');$('boss-hud').classList.toggle('hidden',!boss||state!=='play');if(boss){$('boss-fill').style.width=boss.hp/boss.maxHp*100+'%';$('boss-count').textContent=Math.ceil(boss.hp)+' / '+boss.maxHp;}if(run){$('ability-strike').style.setProperty('--ready',run.attackCd>0?'.3':'1');$('ability-bolt').style.setProperty('--ready',run.special>0?'.3':'1');$('ability-dash').style.setProperty('--ready',run.dash>0?'.3':'1');$('combo').textContent=run.comboWindow>0?t('COMBO')+' '+run.combo+' / 3':t('ENGINEER / FIELD OPERATIVE');}}
let accumulator=0;function frame(t){const dt=Math.min((t-last)/1000,.1);last=t;now=t/1000;accumulator+=dt;while(accumulator>=1/120){update(1/120);accumulator-=1/120;}draw(dt);requestAnimationFrame(frame);}showHangar();initLanguages();document.addEventListener('languagechange',()=>keys.clear());requestAnimationFrame(frame);
// Read-only diagnostics used by browser acceptance tests; never mutates game state.
export function getGameSnapshot(){return{state,mission:mission.id,run:run?JSON.parse(JSON.stringify(run)):null,render:{engine:'WebGL 2 / Three.js',geometries:world.renderer.info.memory.geometries,drawCalls:world.renderer.info.render.calls}};}


function exportReport(){const report={version:'0.4',mission:mission.id,completed:run.finished,durationSeconds:run.time,loadout:selection,configuration:cfg,results:{sites:run.scans,returnedMB:run.returned,batteryWh:run.wh,damage:run.damage,powerMode:run.powerMode},decisions:run.log,telemetry:run.telemetry,observations:run.nodes.flatMap((n,i)=>n.done?[{site:i+1,arenaCoordinates:{x:n.x,y:n.y},syntheticSpectrum:n.spectrum??null}]:[]),scienceObjective:cfg.objective,flightPlan:cfg.orbit,learning:{solar:'P = P_1AU / distance_AU² × illumination',battery:'ΔWh = (generation_W − demand_W) × electrical_seconds / 3600',electricalTimeScale:30},limits:['Illustrative hardware and resource budgets','Fictional combat, heat and contact windows','No real spacecraft or operational trajectory validation','Authored synthetic spectra, not NASA observations or material identifications'],trajectoryReferences:orbitSources,sources:sources.map(({name,url,use,status})=>({name,url,use,status}))};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='astra-'+mission.id+'-mission-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
